package android.app;
import java.util.*;
public class NotificationManager {public static final int IMPORTANCE_NONE=0,IMPORTANCE_LOW=2,IMPORTANCE_HIGH=4;public boolean enabled=true,failNotify;public int posted;public String lastTag;public Notification last;private final Map<String,NotificationChannel> channels=new HashMap<>();public boolean areNotificationsEnabled(){return enabled;}public NotificationChannel getNotificationChannel(String id){return channels.get(id);}public void createNotificationChannel(NotificationChannel channel){channels.putIfAbsent(channel.id,channel);}public void notify(String tag,int id,Notification notification){if(failNotify)throw new SecurityException("denied");posted++;lastTag=tag;last=notification;}public void replaceChannel(NotificationChannel channel){channels.put(channel.id,channel);}}
